<script>document.addEventListener('DOMContentLoaded',function(){const b=document.getElementById('selectAllRollPages');if(!b)return;b.addEventListener('click',function(){const boxes=[...document.querySelectorAll('.roll-page-check')],all=boxes.every(x=>x.checked);boxes.forEach(x=>x.checked=!all);b.textContent=all?'Select all':'Clear all';});});</script>
<script>
document.addEventListener('DOMContentLoaded',function(){
    const options=['view','create','update','delete','upload','approve','export'];
    document.querySelectorAll('.rolls-ui input[name^="action"]').forEach(function(input){
        if(input.type==='checkbox'||input.dataset.enhanced)return;
        input.dataset.enhanced='1';const name=input.name,value=input.value||'view',selected=value.split(',').map(v=>v.trim().toLowerCase()).filter(Boolean);input.type='hidden';
        const box=document.createElement('div');box.className='permission-actions mt-2';[...new Set(options.concat(selected))].forEach(function(action){const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.value=action;check.checked=selected.includes(action);check.dataset.actionName=name;label.append(check,' '+action.charAt(0).toUpperCase()+action.slice(1));box.append(label);});input.parentNode.append(box);input.closest('form').addEventListener('submit',function(){input.value=[...box.querySelectorAll('input:checked')].map(c=>c.value).join(',');});
    });
});
</script>
